PRAGMA foreign_keys=ON;
CREATE TABLE schema_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL) STRICT;
CREATE TABLE products(sku TEXT PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,brand TEXT NOT NULL,size TEXT,flavor TEXT,aliases_json TEXT NOT NULL,attributes_json TEXT NOT NULL,source_origin_json TEXT NOT NULL) STRICT;
CREATE TABLE stores(id TEXT PRIMARY KEY,name TEXT NOT NULL,address TEXT NOT NULL,lat REAL NOT NULL,lng REAL NOT NULL,source_origin_json TEXT NOT NULL,coordinate_source TEXT NOT NULL,coordinate_accuracy TEXT NOT NULL) STRICT;
CREATE TABLE sessions(id TEXT PRIMARY KEY,generation INTEGER NOT NULL DEFAULT 1,revision INTEGER NOT NULL DEFAULT 0,next_sequence INTEGER NOT NULL DEFAULT 1,clock_offset_ms INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL) STRICT;
CREATE TABLE actors(session_id TEXT NOT NULL REFERENCES sessions(id),generation INTEGER NOT NULL,id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('customer','merchant')),display_name TEXT NOT NULL,store_id TEXT REFERENCES stores(id),PRIMARY KEY(session_id,generation,id)) STRICT;
CREATE TABLE conditions(session_id TEXT NOT NULL REFERENCES sessions(id),generation INTEGER NOT NULL,store_id TEXT NOT NULL REFERENCES stores(id),sku TEXT NOT NULL REFERENCES products(sku),version INTEGER NOT NULL,sale_price_krw INTEGER NOT NULL CHECK(sale_price_krw>=0),purchase_cost_krw INTEGER NOT NULL CHECK(purchase_cost_krw>0),minimum_order_qty INTEGER NOT NULL CHECK(minimum_order_qty>0),order_multiple INTEGER NOT NULL CHECK(order_multiple>0),available_order_qty INTEGER NOT NULL CHECK(available_order_qty>=0),assortment_status TEXT NOT NULL,stock_qty INTEGER CHECK(stock_qty IS NULL OR stock_qty>=0),observation_status TEXT NOT NULL,observed_at INTEGER,supply_status TEXT NOT NULL,reason TEXT,orderable_until INTEGER,PRIMARY KEY(session_id,generation,store_id,sku)) STRICT;
CREATE TABLE purchase_requests(session_id TEXT NOT NULL,generation INTEGER NOT NULL,id TEXT NOT NULL,actor_id TEXT NOT NULL,store_id TEXT NOT NULL REFERENCES stores(id),sku TEXT NOT NULL REFERENCES products(sku),quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 20 AND typeof(quantity)='integer'),accepted_price_krw INTEGER NOT NULL CHECK(accepted_price_krw>=0),sequence INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','review_required','allocated','reserved','cancelled')),is_active INTEGER NOT NULL CHECK(is_active IN(0,1)),pending_reason TEXT,consent_version INTEGER NOT NULL,payment_cycle INTEGER NOT NULL,version INTEGER NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(session_id,generation,id),FOREIGN KEY(session_id,generation,actor_id) REFERENCES actors(session_id,generation,id)) STRICT;
CREATE UNIQUE INDEX active_request ON purchase_requests(session_id,generation,actor_id,store_id,sku) WHERE is_active=1;
CREATE INDEX request_queue ON purchase_requests(session_id,generation,store_id,sku,sequence);
CREATE TABLE consent_revisions(session_id TEXT NOT NULL,generation INTEGER NOT NULL,request_id TEXT NOT NULL,version INTEGER NOT NULL,terms_version TEXT NOT NULL,sku TEXT NOT NULL,store_id TEXT NOT NULL,quantity INTEGER NOT NULL,unit_price_krw INTEGER NOT NULL,consent_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,PRIMARY KEY(session_id,generation,request_id,version),FOREIGN KEY(session_id,generation,request_id) REFERENCES purchase_requests(session_id,generation,id)) STRICT;
CREATE TABLE policies(session_id TEXT NOT NULL,generation INTEGER NOT NULL,id TEXT NOT NULL,store_id TEXT NOT NULL REFERENCES stores(id),enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),sku_scope_json TEXT NOT NULL,category_scope_json TEXT NOT NULL,daily_budget_krw INTEGER NOT NULL CHECK(daily_budget_krw>=0),max_quantity_per_review INTEGER CHECK(max_quantity_per_review IS NULL OR max_quantity_per_review>0),version INTEGER NOT NULL,approved_by TEXT,approved_at INTEGER,PRIMARY KEY(session_id,generation,id),UNIQUE(session_id,generation,store_id)) STRICT;
CREATE TABLE proposals(session_id TEXT NOT NULL,generation INTEGER NOT NULL,id TEXT NOT NULL,store_id TEXT NOT NULL REFERENCES stores(id),version INTEGER NOT NULL,status TEXT NOT NULL,source_fingerprint TEXT NOT NULL,constraints_json TEXT NOT NULL,lines_json TEXT NOT NULL,deferred_json TEXT NOT NULL,total_krw INTEGER NOT NULL,history_json TEXT NOT NULL,order_id TEXT,PRIMARY KEY(session_id,generation,id)) STRICT;
CREATE TABLE orders(session_id TEXT NOT NULL,generation INTEGER NOT NULL,id TEXT NOT NULL,store_id TEXT NOT NULL REFERENCES stores(id),approval_type TEXT NOT NULL,policy_version INTEGER NOT NULL,budget_day TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(session_id,generation,id)) STRICT;
CREATE TABLE order_lines(session_id TEXT NOT NULL,generation INTEGER NOT NULL,id TEXT NOT NULL,order_id TEXT NOT NULL,sku TEXT NOT NULL REFERENCES products(sku),ordered_qty INTEGER NOT NULL CHECK(ordered_qty>0),confirmed_qty INTEGER CHECK(confirmed_qty BETWEEN 0 AND ordered_qty),received_qty INTEGER CHECK(received_qty IS NULL OR received_qty=confirmed_qty),sale_price_krw INTEGER NOT NULL,purchase_cost_krw INTEGER NOT NULL,condition_version INTEGER NOT NULL,supply_confirmed_at INTEGER,received_at INTEGER,PRIMARY KEY(session_id,generation,id),FOREIGN KEY(session_id,generation,order_id) REFERENCES orders(session_id,generation,id)) STRICT;
CREATE TABLE request_order_links(session_id TEXT NOT NULL,generation INTEGER NOT NULL,id TEXT NOT NULL,request_id TEXT NOT NULL,line_id TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),active INTEGER NOT NULL CHECK(active IN(0,1)),released_reason TEXT,PRIMARY KEY(session_id,generation,id),FOREIGN KEY(session_id,generation,request_id) REFERENCES purchase_requests(session_id,generation,id),FOREIGN KEY(session_id,generation,line_id) REFERENCES order_lines(session_id,generation,id)) STRICT;
CREATE TABLE allocation_sources(session_id TEXT NOT NULL,generation INTEGER NOT NULL,id TEXT NOT NULL,request_id TEXT NOT NULL,cycle INTEGER NOT NULL,line_id TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),status TEXT NOT NULL CHECK(status IN('held','paid','released')),PRIMARY KEY(session_id,generation,id),UNIQUE(session_id,generation,request_id,cycle,line_id),FOREIGN KEY(session_id,generation,request_id) REFERENCES purchase_requests(session_id,generation,id),FOREIGN KEY(session_id,generation,line_id) REFERENCES order_lines(session_id,generation,id)) STRICT;
CREATE TABLE reservations(session_id TEXT NOT NULL,generation INTEGER NOT NULL,id TEXT NOT NULL,request_id TEXT NOT NULL,cycle INTEGER NOT NULL,code TEXT NOT NULL,quantity INTEGER NOT NULL,total_krw INTEGER NOT NULL,status TEXT NOT NULL,hold_expires_at INTEGER,pickup_available_at INTEGER,pickup_deadline_at INTEGER,collected_at INTEGER,PRIMARY KEY(session_id,generation,id),UNIQUE(session_id,generation,request_id,cycle),UNIQUE(session_id,generation,code),CHECK((pickup_available_at IS NULL AND pickup_deadline_at IS NULL) OR pickup_deadline_at=pickup_available_at+172800000),FOREIGN KEY(session_id,generation,request_id) REFERENCES purchase_requests(session_id,generation,id)) STRICT;
CREATE TABLE mock_payments(session_id TEXT NOT NULL,generation INTEGER NOT NULL,id TEXT NOT NULL,request_id TEXT NOT NULL,cycle INTEGER NOT NULL,attempt INTEGER NOT NULL CHECK(attempt IN(1,2)),status TEXT NOT NULL CHECK(status IN('succeeded','failed')),amount_krw INTEGER NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(session_id,generation,id),UNIQUE(session_id,generation,request_id,cycle,attempt),FOREIGN KEY(session_id,generation,request_id) REFERENCES purchase_requests(session_id,generation,id)) STRICT;
CREATE TABLE budget_ledger(session_id TEXT NOT NULL,generation INTEGER NOT NULL,line_id TEXT NOT NULL,store_id TEXT NOT NULL,budget_day TEXT NOT NULL,reserved_krw INTEGER NOT NULL CHECK(reserved_krw>=0),secured_krw INTEGER NOT NULL CHECK(secured_krw>=0),settled INTEGER NOT NULL CHECK(settled IN(0,1)),PRIMARY KEY(session_id,generation,line_id),FOREIGN KEY(session_id,generation,line_id) REFERENCES order_lines(session_id,generation,id)) STRICT;
CREATE TABLE need_records(session_id TEXT NOT NULL,generation INTEGER NOT NULL,id TEXT NOT NULL,actor_id TEXT NOT NULL,store_id TEXT NOT NULL REFERENCES stores(id),original_text TEXT NOT NULL,dialogue_json TEXT NOT NULL,extracted_clues_json TEXT NOT NULL,candidate_skus_json TEXT NOT NULL,identification_status TEXT NOT NULL,reason TEXT NOT NULL,observed_at INTEGER NOT NULL,source_refs_json TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(session_id,generation,id),FOREIGN KEY(session_id,generation,actor_id) REFERENCES actors(session_id,generation,id)) STRICT;
CREATE TABLE recommendation_events(session_id TEXT NOT NULL,generation INTEGER NOT NULL,id TEXT NOT NULL,need_id TEXT NOT NULL,candidate_sku TEXT NOT NULL REFERENCES products(sku),kind TEXT NOT NULL,action TEXT NOT NULL,followup_request_id TEXT,PRIMARY KEY(session_id,generation,id),FOREIGN KEY(session_id,generation,need_id) REFERENCES need_records(session_id,generation,id)) STRICT;
CREATE TABLE notifications(session_id TEXT NOT NULL,generation INTEGER NOT NULL,id TEXT NOT NULL,actor_id TEXT NOT NULL,event_key TEXT NOT NULL,type TEXT NOT NULL,body TEXT NOT NULL,created_at INTEGER NOT NULL,read_at INTEGER,PRIMARY KEY(session_id,generation,id),UNIQUE(session_id,generation,actor_id,event_key,type),FOREIGN KEY(session_id,generation,actor_id) REFERENCES actors(session_id,generation,id)) STRICT;
CREATE TABLE command_results(session_id TEXT NOT NULL,generation INTEGER NOT NULL,id TEXT NOT NULL,actor_id TEXT NOT NULL,fingerprint TEXT NOT NULL,result_json TEXT NOT NULL,PRIMARY KEY(session_id,generation,id)) STRICT;
CREATE TABLE events(session_id TEXT NOT NULL,generation INTEGER NOT NULL,id TEXT NOT NULL,command_id TEXT NOT NULL,type TEXT NOT NULL,entity_id TEXT,created_at INTEGER NOT NULL,PRIMARY KEY(session_id,generation,id)) STRICT;
CREATE TABLE demo_payment_outcomes(session_id TEXT NOT NULL,generation INTEGER NOT NULL,actor_id TEXT NOT NULL,outcomes_json TEXT NOT NULL,PRIMARY KEY(session_id,generation,actor_id),FOREIGN KEY(session_id,generation,actor_id) REFERENCES actors(session_id,generation,id)) STRICT;

CREATE TABLE agent_runs(session_id TEXT NOT NULL,generation INTEGER NOT NULL,id TEXT NOT NULL,request_id TEXT NOT NULL,actor_id TEXT NOT NULL,status TEXT NOT NULL,record_json TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(session_id,generation,id),UNIQUE(session_id,generation,request_id),FOREIGN KEY(session_id,generation,actor_id) REFERENCES actors(session_id,generation,id)) STRICT;
